from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True)
class Report:
    id: str
    tenant_id: str
    data: bytes
    filename: str


@dataclass(frozen=True)
class Download:
    body: bytes
    filename: str
    content_type: str


class Reports(Protocol):
    def get(self, report_id: str) -> Report | None: ...


def download(report_id: str, tenant_id: str, reports: Reports) -> Download:
    report = reports.get(report_id)
    if report is None:
        raise LookupError("report not found")
    return Download(report.data, report.filename, "text/csv")
